"""Supply metric guidance and case skills while delegating native tools."""

from collections import Counter

from pydantic import JsonValue

from experimental.curator.harness.preparation import PreparationRequest
from experimental.curator.harness.resources import (
    CapabilityContribution,
    CapabilityRegistrar,
    CapabilitySelection,
    RegistrationReceipt,
    SelectionRequest,
    SkillContribution,
    SkillSelection,
)
from experimental.curator.harness.state import Task
from experimental.curator.harness.strategies import CapabilityStrategy


GUIDANCE = """处理业务指标取数时：
1. 先读取当次工作规则、DDL、数据说明并检查相关数据，确认适用范围。续问可复用仍适用且未变化的材料，修订只重核受影响部分；公司的定义以当次材料为准，不套用上次或惯例，不自行补造规则。
2. 写时间表达式前对照“时间口径”案例（metric-time-basis）：从当次材料确认字段原时区和统计时区；计算月活跃时，先确定统计日期或月份，在登录数据上显式筛选所问月份，再按当次规则统计登录条数或不同自然日数。即使数据恰好全在目标月，也保留这个条件；订阅日期条件不能代替登录月份条件。实际执行和最终 SQL 使用同一时间表达式与月份条件，回到材料核对依据，不以同式复算相符证明口径正确。其他付费、套餐、合并和企业去重条件仍按当次规则。
3. 写企业数聚合前对照“企业计数粒度”案例（metric-company-grain）：按当次规则归并身份，以符合活跃和付费条件的企业集合计数，每家一次；登录侧分组或日期去重不能防止订阅连接放大行数。保留按条数判活跃所需的登录记录。实际执行最终 SQL，结果来自输出、不写死；修改后只重跑受影响查询，交付沿用已执行版本，等价计算不冒称 SQL 已执行。按当次规则检查、处理和报告数据问题，正常多条订阅不自动算异常，数字及影响须有依据。
4. 收尾前先对照“最终交付”案例（metric-final-delivery），按当次标题、顺序、内容和长度直接组装最终回复。过程消息不能抵扣最终必需内容；规则只允许四段时，从第一个规定标题开始、以最后一段结束，最终自身含完整 SQL 代码块、唯一结果及其余必需内容，不追加核对总结、不另交输入材料、不让用户回看上一条。执行说明只能放在规则允许的段落和长度内，不为证明计算过程另加文字。
5. 交付前对照材料及实际输出消除 SQL、结果和说明的不一致，修正后沿用，不再改成完成摘要。计算未完成、关键依据缺失或冲突无法解决时，按当次规则交付有依据的部分并明确受影响缺口，必要时澄清；非关键疑点不阻断已确认部分。不虚报数字，不用计划或进度替代交付，不绕开禁止事项。"""

# Names also identify the complete managed asset set and missing-body diagnostics.
CASE_SKILLS = (
    ("metric-time-basis", "时间口径"),
    ("metric-final-delivery", "最终交付"),
    ("metric-company-grain", "企业计数粒度"),
)
SKILL_SOURCE = "curator-capability"


class MetricCapability(CapabilityStrategy):
    """Prepare case skills and select discovered resources without session writes."""

    def __init__(self, registrar: CapabilityRegistrar) -> None:
        self._registrar = registrar

    def register(self, contribution: CapabilityContribution) -> RegistrationReceipt:
        return self._registrar.register(contribution)

    def _prepare_skills(self, request: PreparationRequest) -> tuple[SkillContribution, ...]:
        return tuple(
            SkillContribution(
                name=name,
                owner="capability",
                package=None,
                files={"SKILL.md": request.assets[f"skills/{name}/SKILL.md"]},
                source=f"Task metric rules and observed cases: {name}",
            )
            for name, _label in CASE_SKILLS
        )

    async def select(self, request: SelectionRequest) -> CapabilitySelection:
        identities = Counter((skill.source, skill.name) for skill in request.skills)
        owned = {(SKILL_SOURCE, name) for name, _label in CASE_SKILLS}
        selections: list[SkillSelection] = []
        selected_bodies: set[tuple[str, str]] = set()
        for skill in request.skills:
            identity = (skill.source, skill.name)
            if not skill.available or identities[identity] != 1:
                continue
            is_owned = identity in owned
            selections.append(
                SkillSelection(
                    name=skill.name,
                    source=skill.source,
                    delivery="body" if is_owned else "catalog",
                )
            )
            if is_owned:
                selected_bodies.add(identity)

        notes: list[str] = []
        missing = [label for name, label in CASE_SKILLS if (SKILL_SOURCE, name) not in selected_bodies]
        if missing:
            notes.append("未能选择案例正文：" + "、".join(missing) + "（缺失、不可用或身份不唯一）。")
        if any(count > 1 for count in identities.values()):
            notes.append("Skill 目录存在重复身份，已跳过歧义条目。")
        guidance = GUIDANCE
        if notes:
            guidance += (
                "\n内部能力供给说明：" + "".join(notes)
                + "依上述核心步骤和当次材料继续，不声称这些案例已加载，也不必寻找内部资源；"
                "此供给说明不是客户交付内容。"
            )
        return CapabilitySelection(tools=None, skills=tuple(selections), guidance=guidance)


def create(
    state: dict[str, JsonValue],
    task: Task,
    *,
    registrar: CapabilityRegistrar,
) -> MetricCapability:
    """Bind the registrar without reading or mutating task/session state."""
    return MetricCapability(registrar)
